\begin{aligned}
s_i(x) &= y_i + b_i\,t + \frac{M_i}{2}\,t^2 + \frac{M_{i+1} - M_i}{6h}\,t^3 \\
b_i &= \frac{y_{i+1} - y_i}{h} - \frac{h}{6}\,(2M_i + M_{i+1})
\end{aligned}

\begin{pmatrix}
4 & 1 & & & \\
