\end{pmatrix}
\begin{pmatrix} M_1 \\ M_2 \\ \vdots \\ M_{n-2} \\ M_{n-1} \end{pmatrix}
= \frac{6}{h^2} \begin{pmatrix} y_0 - 2y_1 + y_2 \\ y_1 - 2y_2 + y_3 \\ \vdots \\ y_{n-3} - 2y_{n-2} + y_{n-1} \\ y_{n-2} - 2y_{n-1} + y_n \end{pmatrix}

